    height: 40px;
    padding-inline-start: 4px;
    margin-block-end: var(--g-spacing-2);
    white-space: nowrap;
}

.sidebar__logo {
    flex: none;
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    border-radius: 8px;
